/**
 * The invented catalogue the screenshots photograph.
 *
 * Not one datum comes from the real catalogue: the funds, the artists, the works,
 * the collectors and the exhibitions are made up here, and the photographs are
 * generated by `artwork_images.py`. The reason is not aesthetic — the real base
 * holds third parties' personal data (`parties.contact` is the most delicate row of
 * the whole RLS matrix) and a public page is exactly where that cannot end up.
 *
 * The shape, on the other hand, IS the real one: the same tables, the same columns
 * and the same enumerated values as the applied schema, because what is being
 * photographed is the actual application and it queries what it queries.
 */

const uuid = (n) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`

