function dateText(seed) {
  if (seed.dateNote) return seed.dateNote
  if (seed.years[0] === null) return ''
  const range = seed.years[1] ? `${seed.years[0]}-${seed.years[1]}` : `${seed.years[0]}`
  return `${seed.approximate ? 'c. ' : ''}${range}${seed.unconfirmed ? ' [?]' : ''}`
}

function artwork(seed, fund, prefix, index) {
  return {
    catalog_id: `${prefix}-${String(seed.n).padStart(4, '0')}`,
    artist: fund,
    title: seed.title,
    attributed_title: seed.attributed ?? 'NOT_APPLICABLE',
    artwork_type: seed.type,
    series: seed.series ?? '',
    execution_date: dateText(seed),
    start_year: seed.years[0],
    end_year: seed.years[1],
    approximate_date: Boolean(seed.approximate),
    unconfirmed_date: Boolean(seed.unconfirmed),
    date_note: seed.dateNote ?? '',
    technique: seed.technique,
    support: seed.support,
    height_cm: seed.size[0],
    width_cm: seed.size[1],
    depth_cm: seed.size[2],
    signed: seed.signed,
    signature_description: seed.signature ?? '',
    dated_on_artwork: seed.dated,
    conservation_status: seed.conservation,
    physical_place_id: seed.place,
    existence_status: seed.existence ?? 'PRESERVED',
    photographed: true,
    measurements_verified: !seed.fresh,
    inventory_phase_completed: !seed.fresh,
    documentation_phase_completed: Boolean(seed.complete),
    catalog_record_complete: Boolean(seed.complete),
    inventory_process_notes: seed.notes ?? '',
    updated_at: `2026-0${(index % 8) + 1}-1${index % 9}T09:${10 + index}:00Z`,
    basic_updated_at: `2026-0${(index % 8) + 1}-1${index % 9}T09:${10 + index}:00Z`,
    updated_by: USER.id,
    active: true,
    image: index % 12,
  }
}

export const ARTWORKS = [
  ...WORK_SEED.map((s, i) => artwork(s, 'ROTILI', 'AF', i)),
  ...OTHER_SEED.map((s, i) => artwork(s, 'RUIZ_CAMPINS', 'VO', i + 9)),
]

/**
 * The photographs. The first work carries three shots —general, back and
 * signature detail— because that trio is what the record's carousel is for; the
 * rest carry one.
 */
export const IMAGES = []
let imageNumber = 0
for (const row of ARTWORKS) {
  const base = `work-${String(row.image).padStart(2, '0')}`
  const shots = [{ suffix: '', shot: 'GENERAL' }]
  if (row.catalog_id === 'AF-0001') {
    shots.push({ suffix: '-back', shot: 'BACK' }, { suffix: '-signature', shot: 'SIGNATURE_DETAIL' })
  }
  shots.forEach((shot, order) => {
    imageNumber += 1
    IMAGES.push({
      image_id: uuid(1000 + imageNumber),
      catalog_id: row.catalog_id,
      thumbnail_path: `${base}${shot.suffix}-thumb.jpg`,
      derivative_path: `${base}${shot.suffix}.jpg`,
      master_path: `${base}${shot.suffix}-master.jpg`,
      shot_type: shot.shot,
      index_image: order === 0,
      photo_date: '2026-03-12',
      sort_order: order + 1,
      rotation: 0,
      crop_x: null,
      crop_y: null,
      crop_width: null,
      crop_height: null,
      corner_nw_x: null,
      corner_nw_y: null,
      corner_ne_x: null,
      corner_ne_y: null,
      corner_se_x: null,
      corner_se_y: null,
      corner_sw_x: null,
      corner_sw_y: null,
      provenance: 'OWN',
      credit: 'Archivo del fondo',
      author: 'Marta Sedano',
      color_source: order === 0 ? 'NEUTRAL_PICKED' : null,
      color_reference: order === 0 ? 'TARGET_CARD' : 'NONE',
      light_preset: 'DAYLIGHT',
      active: true,
    })
  })
}

export const REPRESENTATIVE = ARTWORKS.map((row) => {
  const first = IMAGES.find((image) => image.catalog_id === row.catalog_id)
  return {
    catalog_id: row.catalog_id,
    image_id: first.image_id,
    thumbnail_path: first.thumbnail_path,
    derivative_path: first.derivative_path,
    manually_chosen: false,
  }
})

